291	    /**
292	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
293	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
294	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
295	     *
296	     * @param ownerFieldsDto the submitted owner fields
297	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
298	     *                                     name of every offending field
299	     */
300	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
301	        List<String> missingFields = new ArrayList<>();
302	        if (isBlank(ownerFieldsDto.getFirstName())) {
303	            missingFields.add("firstName");
304	        }
305	        if (isBlank(ownerFieldsDto.getLastName())) {
306	            missingFields.add("lastName");
307	        }
308	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
309	            missingFields.add("address");
310	        }
311	        if (isBlank(ownerFieldsDto.getCity())) {
312	            missingFields.add("city");
313	        }
314	        if (isBlank(ownerFieldsDto.getTelephone())) {
315	            missingFields.add("telephone");
316	        }
317	        if (!missingFields.isEmpty()) {
318	            throw new InvalidOwnerFieldsException(missingFields);
319	        }
320	    }
321	
322	    private boolean isBlank(String value) {
323	        return value == null || value.isBlank();
324	    }
325	
326	    /**
327	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
328	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
329	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
330	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
331	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
332	     *
333	     * @param telephone the raw telephone value submitted by the client
334	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
335	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
336	     *                                     400 response
337	     */
338	    private String normalizeTelephone(String telephone) {
339	        String e164 = toE164(telephone);
340	        if (e164 == null) {
341	            throw new InvalidOwnerFieldsException(List.of("telephone"));
342	        }
343	        return e164;
344	    }
345	
346	    /**
347	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
348	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
349	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
350	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
351	     *
352	     * @param telephone the raw telephone value, possibly {@code null}
353	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
354	     */
355	    private String toE164(String telephone) {
356	        if (telephone == null) {
357	            return null;
358	        }
359	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
360	        boolean hasPlus = cleaned.startsWith("+");
361	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
362	        String nationalSignificant = hasPlus
363	            ? digits
364	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
365	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
366	            return null;
367	        }
368	        return "+" + nationalSignificant;
369	    }
370	
371	    /**
372	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
373	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
374	     * returned value is that address lower-cased.
375	     *
376	     * @param email the raw email value submitted by the client, or {@code null} if omitted
377	     * @return the lower-cased email, or {@code null} if none was supplied
378	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
379	     *                                     yielding a 400 response
380	     */
381	    private String normalizeEmail(String email) {
382	        if (email == null) {
383	            return null;
384	        }
385	        if (!EMAIL_PATTERN.matcher(email).matches()) {
386	            throw new InvalidOwnerFieldsException(List.of("email"));
387	        }
388	        return email.toLowerCase(Locale.ROOT);
389	    }
390	
391	    /**
392	     * Counts the existing owners that, before this create, already share the given first name and
393	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
394	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
395	     * been saved yet, so it is never included in the count.
396	     *
397	     * @param firstName the first name of the owner being created
398	     * @param lastName  the last name of the owner being created
399	     * @return the number of existing owners sharing both names
400	     */
401	    private int countNamesakes(String firstName, String lastName) {
402	        String normalizedFirstName = normalizeForComparison(firstName);
403	        String normalizedLastName = normalizeForComparison(lastName);
404	        return (int) this.clinicService.findAllOwners().stream()
405	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
406	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
407	            .count();
408	    }
409	
410	    /**
411	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
412	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
413	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
414	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
415	     *
416	     * @param city     the owner's city
417	     * @param lastName the owner's last name
418	     * @return the formatted customer code
419	     */
420	    private String generateCustomerCode(String city, String lastName) {
421	        String city3 = first3Letters(city);
422	        String last3 = first3Letters(lastName);
423	        int sequence = countOwnersInCity(city) + 1;
424	        return String.format("%s-%s-%04d", city3, last3, sequence);
425	    }
426	
427	    /**
428	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
429	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
430	     *
431	     * @param value the value to abbreviate
432	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
433	     */
434	    private String first3Letters(String value) {
435	        String letters = value.replaceAll("[^\\p{L}]", "");
436	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
437	    }
438	
439	    /**
440	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
441	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
442	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
443	     * has not been saved yet, so it is never included in the count.
444	     *
445	     * @param city the city of the owner being created
446	     * @return the number of existing owners in that city
447	     */
448	    private int countOwnersInCity(String city) {
449	        String normalizedCity = normalizeForComparison(city);
450	        return (int) this.clinicService.findAllOwners().stream()
451	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
452	            .count();
453	    }
454	
455	    /**
456	     * Rejects creation of an owner whose city already contains the maximum number of owners
457	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
458	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
459	     *
460	     * @param city the city of the owner being created
461	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
462	     *                                      owners, yielding a 409 Conflict response
463	     */
464	    private void rejectCityAtCapacity(String city) {
465	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
466	            throw new OwnerCityAtCapacityException(city);
467	        }
468	    }
469	
470	    /**
471	     * Rejects creation of an owner once the given business day has already reached its daily quota
472	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
473	     * being that day — the adjusted business day the owner being created will carry — so the quota
474	     * applies per business day. The owner being created has not been saved yet, so it is never
475	     * included in the count.
476	     *
477	     * @param registrationDate the adjusted business-day registration date of the owner being created
478	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
479	     *                                         carry that registration date, yielding a
480	     *                                         429 Too Many Requests response
481	     */
482	    private void rejectDailyLimitReached(LocalDate registrationDate) {
483	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
484	            throw new DailyOwnerLimitReachedException(registrationDate);
485	        }
486	    }
487	
488	    /**
489	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
490	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
491	     *
492	     * @param registrationDate the business day to count owners for
493	     * @return the number of existing owners registered on that day
494	     */
495	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
496	        return this.clinicService.findAllOwners().stream()
497	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
498	            .count();
499	    }
500	
501	    /**
502	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
503	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
504	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
505	     * otherwise.
506	     *
507	     * @param ownerDto the owner response to flag
508	     */
509	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
510	        LocalDate today = toBusinessDay(LocalDate.now());
511	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
512	    }
513	
514	    /**
515	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
516	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
517	     * applies to the effective registration date whether it was supplied in the request or defaulted
518	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
519	     * feeds every value derived from it (such as the membership number's year segment and the daily
520	     * create-limit's per-day bucket).
521	     *
522	     * @param date the effective registration date, supplied or defaulted
523	     * @return the same date when it is a weekday, otherwise the next Monday
524	     */
525	    private LocalDate toBusinessDay(LocalDate date) {
526	        LocalDate adjusted = date;
527	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
528	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
529	            adjusted = adjusted.plusDays(1);
530	        }
531	        return adjusted;
532	    }
533	
534	    /**
535	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
536	     * telephones are converted to E.164 here as well so the comparison is independent of the format
537	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
538	     * ignored rather than matched.
539	     *
540	     * @param telephone the E.164 telephone of the owner being created
541	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
542	     *                                          yielding a 409 Conflict response
543	     */
544	    private void rejectDuplicateTelephone(String telephone) {
545	        boolean inUse = this.clinicService.findAllOwners().stream()
546	            .map(Owner::getTelephone)
547	            .map(this::toE164)
548	            .anyMatch(telephone::equals);
549	        if (inUse) {
550	            throw new DuplicateOwnerTelephoneException(telephone);
551	        }
552	    }
553	
554	    /**
555	     * Rejects creation of an owner whose lower-cased email is already used by any other owner.
556	     * The email has already been normalized to its lower-cased form, and stored emails are
557	     * lower-cased here as well, so the comparison is case-insensitive. An owner being created
558	     * without an email ({@code null}) is never a duplicate, and stored owners without an email
559	     * are ignored rather than matched.
560	     *
561	     * @param email the normalized (lower-cased) email of the owner being created, or {@code null}
562	     *              if none was supplied
563	     * @throws DuplicateOwnerEmailException if another owner already uses this email, yielding a
564	     *                                      409 Conflict response
565	     */
566	    private void rejectDuplicateEmail(String email) {
567	        if (email == null) {
568	            return;
569	        }
570	        boolean inUse = this.clinicService.findAllOwners().stream()
571	            .map(Owner::getEmail)
572	            .filter(existing -> existing != null)
573	            .map(existing -> existing.toLowerCase(Locale.ROOT))
574	            .anyMatch(email::equals);
575	        if (inUse) {
576	            throw new DuplicateOwnerEmailException(email);
577	        }
578	    }
579	
580	    /**
581	     * Rejects creation of an owner whose last name and address both match an existing owner's,
582	     * which marks them as belonging to the same household. Both the last name and the address are
583	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
584	     * that differ only in letter case or spacing are still treated as a match.
585	     *
586	     * @param lastName the last name of the owner being created
587	     * @param address  the address of the owner being created
588	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
589	     *                                          address, yielding a 409 Conflict response
590	     */
591	    private void rejectDuplicateHousehold(String lastName, String address) {
592	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
593	            throw new DuplicateOwnerHouseholdException(lastName, address);
594	        }
595	    }
596	
597	    /**
598	     * Finds every existing owner belonging to the household identified by the given last name and
599	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
600	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
601	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
602	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
603	     * and {@link #assignHousehold}.
604	     *
605	     * @param lastName the last name of the owner being created
606	     * @param address  the address of the owner being created
607	     * @return the existing owners in that household, or an empty list if there are none
608	     */
609	    private List<Owner> findHouseholdMembers(String lastName, String address) {
610	        String normalizedLastName = normalizeForComparison(lastName);
611	        String normalizedAddress = normalizeAddress(address);
612	        return this.clinicService.findAllOwners().stream()
613	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
614	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
615	            .toList();
616	    }
617	
618	    /**
619	     * Enrolls a newly created owner into the household of any existing owner that shares its last
620	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
621	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
622	     * whitespace. When at least one such owner already exists, every member of the household — the
623	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
624	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
625	     * and address is created and back-filled onto the existing members. When no owner yet lives at
626	     * that address under the same last name no identifier is assigned and the owner is created alone.
627	     *
628	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
629	     * @param lastName the last name of the owner being created
630	     * @param address  the address of the owner being created
631	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
632	     */
633	    private String assignHousehold(Owner newOwner, String lastName, String address) {
634	        List<Owner> members = findHouseholdMembers(lastName, address);
635	        if (members.isEmpty()) {
636	            return null;
637	        }
638	        String householdId = members.stream()
639	            .map(Owner::getHouseholdId)
640	            .filter(existing -> existing != null && !existing.isBlank())
641	            .findFirst()
642	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
643	        for (Owner member : members) {
644	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
645	                member.setHouseholdId(householdId);
646	                this.clinicService.saveOwner(member);
647	            }
648	        }
649	        newOwner.setHouseholdId(householdId);
650	        return householdId;
651	    }
652	
653	    /**
654	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
655	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
656	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
657	     * same identifier, so members of one household share a single value.
658	     *
659	     * @param normalizedLastName the household's last name, already normalized for comparison
660	     * @param normalizedAddress  the household's address, already normalized for comparison
661	     * @return the derived household identifier
662	     */
663	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
664	        try {
665	            byte[] digest = MessageDigest.getInstance("SHA-256")
666	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
667	            StringBuilder hex = new StringBuilder(digest.length * 2);
668	            for (byte b : digest) {
669	                hex.append(String.format("%02x", b));
670	            }
671	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
672	        } catch (NoSuchAlgorithmException e) {
673	            throw new IllegalStateException("SHA-256 algorithm not available", e);
674	        }
675	    }
676	
677	    /**
678	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
679	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
680	     * the result is lower-cased.
681	     *
682	     * @param value the value to normalize, possibly {@code null}
683	     * @return the normalized value, or an empty string if {@code value} is {@code null}
684	     */
685	    private String normalizeForComparison(String value) {
686	        if (value == null) {
687	            return "";
688	        }
689	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
690	    }
691	
692	    /**
693	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
694	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
695	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
696	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
697	     * This normalized value is what gets stored and returned, and it is the form every address
698	     * comparison (household duplicate detection and the shared household id) uses.
699	     *
700	     * @param address the raw address value submitted by the client, possibly {@code null}
701	     * @return the normalized address, or an empty string if {@code address} is {@code null}
702	     */
703	    private String normalizeAddress(String address) {
704	        if (address == null) {
705	            return "";
706	        }
707	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
708	        if (collapsed.isEmpty()) {
709	            return collapsed;
710	        }
711	        String[] tokens = collapsed.split(" ");
712	        StringBuilder normalized = new StringBuilder(collapsed.length());
713	        for (int i = 0; i < tokens.length; i++) {
714	            if (i > 0) {
715	                normalized.append(' ');
716	            }
717	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
718	        }
719	        return normalized.toString();
720	    }
721	}
